{
  "name": "pairwise_pref_loss",
  "intuition": "This loss compares pairs of sequences using their log probabilities and a cost gap signal. By penalizing less preferred sequences (higher cost gap values), it encourages the model to produce outputs with lower cost. The pairwise structure captures relative differences, which is effective for preference learning in RL4CO tasks.",
  "pseudocode": "loss = mean over pairs of [logsigmoid((log_prob_w - log_prob_l) * (cost_gap - threshold))] with gradient only on the relevant terms",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "cost_difference",
    "link_family": "logistic",
    "agg_family": "pairwise",
    "constraint_family": "pairwise_comparison",
    "other_hparams": "none"
  },
  "operators_used": ["logsigmoid", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    cost_gap = batch.get('cost_gap', ops.zeros_like(log_prob_w))\n    weight = batch['weight']\n    # Compute preference signals\n    diff = ops.sub(log_prob_w, log_prob_l)\n    signal = ops.sub(cost_gap, ops.constant(0.0))  # using 0.0 as threshold\n    # Apply logistic link\n    loss_terms = ops.logsigmoid(ops.mul(diff, signal))\n    # Weight the loss\n    weighted_loss = ops.mul(loss_terms, weight)\n    # Aggregate to scalar\n    loss = ops.mean(weighted_loss)\n    return loss"
}

