{
  "name": "pairwise_pref_loss",
  "intuition": "This loss compares pairwise log probabilities to encourage the model to assign higher probabilities to preferred options. By using logsigmoid on the difference, it emphasizes relative ranking, making the model learn to prefer better options consistently. This approach directly encodes preference signals and leverages pairwise comparisons, leading to robust preference modeling.",
  "pseudocode": "loss = -mean(logsigmoid(log_prob_w - log_prob_l) * (cost_b - cost_a))",
  "hyperparams": {
    "paradigm_family": "discrete-rank",
    "signal_family": "preference",
    "link_family": "logits",
    "agg_family": "pairwise",
    "constraint_family": "monotonic"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    cost_a = batch.get('cost_a', None)\n    cost_b = batch.get('cost_b', None)\n    # Compute the difference in log probabilities\n    diff_log_prob = log_prob_w - log_prob_l\n    # Preference signal: logsigmoid of the difference\n    pref_signal = ops.logsigmoid(diff_log_prob)\n    # Optionally multiply by the cost difference to emphasize preferred options\n    cost_diff = (cost_b - cost_a) if (cost_a is not None and cost_b is not None) else 1.0\n    weighted_signal = pref_signal * cost_diff\n    # Aggregate over batch to produce scalar loss\n    loss = -ops.mean(weighted_signal)\n    return loss"
}

