  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    zeros = lpw.new_zeros(lpw.shape)\n    cost_a = batch.get('cost_a', zeros)\n    cost_b = batch.get('cost_b', zeros)\n    cost_gap = cost_b - cost_a\n    diff = lpw - lpl\n    cost_gap_clamped = ops.clamp(cost_gap, min=eps)\n    pref_signal = ops.logsigmoid(diff)\n    weighted_signal = pref_signal * cost_gap_clamped * weight\n    loss = -ops.mean(weighted_signal)\n    return loss\n"
}

