  "name": "pairwise_tanh_advantage_gap",
  "intuition": "This loss models the difference between log probabilities in relation to the advantage gap, normalized and scaled by regret. Using tanh on the squared deviation encourages soft satisfaction of the preference ordering, promoting stability and differentiability in preference learning.",
  "pseudocode": "adv_gap = advantage_w - advantage_l\nregret = delta_regret\ngap_norm = normalize(adv_gap)\nscaled_diff = (log_prob_w - log_prob_l) / (abs(regret) + epsilon)\nloss_per_pair = tanh((scaled_diff - gap_norm) ** 2)\nloss = mean(weight * loss_per_pair)",
  "hyperparams": {
    "paradigm_family": "pairwise_regression",
    "signal_family": "advantage_gap_delta_regret",
    "link_family": "tanh_squared_penalty",
    "agg_family": "weighted_mean",
    "constraint_family": "soft_saturation",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "tanh", "sub", "mul", "div", "abs", "mean", "normalize", "add", "pow"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "delta_regret"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    regret = batch['delta_regret']\n    adv_gap = adv_w - adv_l\n    gap_norm = ops.normalize(adv_gap)\n    safe_regret = ops.abs(regret) + 1e-6\n    scaled_diff = (lpw - lpl) / safe_regret\n    diff_squared = ops.pow(ops.sub(scaled_diff, gap_norm), 2)\n    penalty = ops.tanh(diff_squared)\n    loss = ops.mean(penalty * weight)\n    return loss"
}

